import os
import urllib
import mimetypes
import logging

logger = logging.getLogger(APP_NAME)

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            guessed = mimetypes.guess_type(self.path)[0]

            try:
                # guess_type() doesn't handle apostrophes well, try to convert urllib path name
                unquoted_path = urllib.unquote(self.path)
                url_safe = False
            except TypeError:
                unquoted_path = self.path
                url_safe = True

            if guessed is None:
                guessed = mimetypes.guess_type(unquoted_path)[0]

            if guessed is None and not url_safe:
                # Convert to unicode because guessed_type() returns str on Python 2/3
                guessed = mimetypes.guess_type(unquoted_path.decode('utf-8'))[0]

            self.type = guessed

    @staticmethod
    def get_objects(path):
        objects = []

        if path:
            try:
                for name in os.listdir(path):
                    object_path = os.path.join(path, name)
                    objects.append(Object(object_path))
            except OSError, error:
                logger.error('ERROR_ACCESS:', error)

        return objects

